package server

// launchPollerBatch is the future production launch boundary. The creator
// owns the immutable batch and must start every entry once, outside mu, before
// any readiness wait. Phase A leaves worker launch unwired.
func (m *runObservationManager) launchPollerBatch([]*runObservationPoller) {}

// claimPollerReadStart is the real mu-protected read-eligibility transition
// shared by initial and recurring reads. Phase A intentionally refuses all
// starts until the manager lifecycle is implemented.
func (m *runObservationManager) claimPollerReadStart(*runObservationPoller) bool { return false }

// runPoller is the sole future worker entry point. Phase A has no worker body.
func (m *runObservationManager) runPoller(*runObservationPoller) {}

// runPollerFromClaim is the mandatory continuation used by runPoller after
// every eligibility decision. Tests stage Stop through this same production
// boundary; Phase A leaves the continuation unwired.
func (m *runObservationManager) runPollerFromClaim(*runObservationPoller, bool) {}
